// Core tests: the 17 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every expected value below was computed by hand from the
// SPEC's rules; the hand derivations are listed in AUTHOR-CHECK.md
// and were independently rechecked with an exact-rational script
// (Fraction arithmetic, half-up only on the total).

import assert from "node:assert/strict";
import test from "node:test";
import { countText, formatDuration, run } from "../public/js/core/reading-time.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  text: "The quick brown fox jumps over the lazy dog",
  zhSilentRate: "400",
  zhSpeakRate: "240",
  enSilentRate: "200",
  enSpeakRate: "150",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: mixed text counts and rounds only once on the total", () => {
  // 「我想學 English words 每天」: 5 CJK + 2 words.
  // Silent: 5*60/400 + 2*60/200 = 0.75 + 0.6 = 1.35 -> 1
  // (rounding each part first would give 1 + 1 = 2).
  // Speaking: 5*60/240 + 2*60/150 = 1.25 + 0.8 = 2.05 -> 2.
  const mixed = run({
    text: "我想學 English words 每天",
    zhSilentRate: "400",
    zhSpeakRate: "240",
    enSilentRate: "200",
    enSpeakRate: "150",
  });
  assert.deepEqual(mixed.result, {
    cjkChars: 5,
    latinWords: 2,
    silentSeconds: 1,
    speakSeconds: 2,
    silentDisplay: "0:01",
    speakDisplay: "0:02",
  });
});

test("boundary: text of exactly 100,000 UTF-16 units succeeds; 100,001 is INPUT_LIMIT", () => {
  // "a" repeated 100,000 times is a single token with one ASCII
  // letter: 0 CJK, 1 word; silent 60/200 = 0.3 -> 0, speaking
  // 60/150 = 0.4 -> 0.
  const atLimit = run({ ...base, text: "a".repeat(100000) });
  assert.equal(atLimit.ok, true);
  assert.deepEqual(atLimit.result, {
    cjkChars: 0,
    latinWords: 1,
    silentSeconds: 0,
    speakSeconds: 0,
    silentDisplay: "0:00",
    speakDisplay: "0:00",
  });
  assert.deepEqual(errorOf({ ...base, text: "a".repeat(100001) }), {
    code: "INPUT_LIMIT",
    field: "text",
    row: null,
  });
});

test("boundary: each rate at its lower bound 50 and its own upper bound succeeds", () => {
  const lower = run({ ...base, zhSilentRate: "50", zhSpeakRate: "50", enSilentRate: "50", enSpeakRate: "50" });
  assert.equal(lower.ok, true);
  // 9 words: silent 9*60/50 = 10.8 -> 11; speaking 9*60/50 = 10.8 -> 11.
  assert.equal(lower.result.silentSeconds, 11);
  assert.equal(lower.result.speakSeconds, 11);
  const upper = run({
    ...base,
    zhSilentRate: "2000",
    zhSpeakRate: "1200",
    enSilentRate: "1000",
    enSpeakRate: "600",
  });
  assert.equal(upper.ok, true);
  assert.equal(upper.result.silentSeconds, 1);
  assert.equal(upper.result.speakSeconds, 1);
});

test("boundary: rate 49 and each upper bound + 1 are RANGE; rate 0 is RANGE", () => {
  assert.deepEqual(errorOf({ ...base, zhSilentRate: "49" }), {
    code: "RANGE",
    field: "zhSilentRate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, zhSilentRate: "2001" }), {
    code: "RANGE",
    field: "zhSilentRate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, zhSpeakRate: "1201" }), {
    code: "RANGE",
    field: "zhSpeakRate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, enSilentRate: "1001" }), {
    code: "RANGE",
    field: "enSilentRate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, enSpeakRate: "601" }), {
    code: "RANGE",
    field: "enSpeakRate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, enSilentRate: "0" }), {
    code: "RANGE",
    field: "enSilentRate",
    row: null,
  });
});

test("capacity: a 9-unit rate value is INPUT_LIMIT; the text limit is checked first", () => {
  for (const field of ["zhSilentRate", "zhSpeakRate", "enSilentRate", "enSpeakRate"]) {
    assert.deepEqual(errorOf({ ...base, [field]: "123456789" }), {
      code: "INPUT_LIMIT",
      field,
      row: null,
    });
  }
  // 100,001 units beats a surrogate error: capacity is checked first.
  assert.deepEqual(errorOf({ ...base, text: `a${"\uD800"}`.repeat(50001) }), {
    code: "INPUT_LIMIT",
    field: "text",
    row: null,
  });
});

test("grammar: signs, spaces, decimals, exponents, leading zeros and non-ASCII digits are INTEGER_FORMAT", () => {
  for (const bad of ["-400", "+400", "400 ", " 400", "400.0", "4e2", "0400", "00", "４００", "400.5"]) {
    assert.deepEqual(errorOf({ ...base, zhSilentRate: bad }), {
      code: "INTEGER_FORMAT",
      field: "zhSilentRate",
      row: null,
    });
  }
  // "0" alone is valid grammar; it fails only on range.
  assert.deepEqual(errorOf({ ...base, zhSilentRate: "0" }), {
    code: "RANGE",
    field: "zhSilentRate",
    row: null,
  });
});

test("empty: empty text and empty rates are EMPTY, in field order", () => {
  assert.deepEqual(errorOf({ ...base, text: "" }), {
    code: "EMPTY",
    field: "text",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, zhSilentRate: "" }), {
    code: "EMPTY",
    field: "zhSilentRate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, enSpeakRate: "" }), {
    code: "EMPTY",
    field: "enSpeakRate",
    row: null,
  });
  // The text field reports before a bad rate.
  assert.deepEqual(errorOf({ ...base, text: "", zhSilentRate: "bad" }), {
    code: "EMPTY",
    field: "text",
    row: null,
  });
  // The first bad rate in field order reports first.
  assert.deepEqual(errorOf({ ...base, zhSilentRate: "bad", enSilentRate: "bad" }), {
    code: "INTEGER_FORMAT",
    field: "zhSilentRate",
    row: null,
  });
});

test("unicode: a lone surrogate in the text or in a rate is UNICODE", () => {
  assert.deepEqual(errorOf({ ...base, text: "a\uD800b" }), {
    code: "UNICODE",
    field: "text",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, text: "a\uDC00b" }), {
    code: "UNICODE",
    field: "text",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, zhSilentRate: "\uD800" }), {
    code: "UNICODE",
    field: "zhSilentRate",
    row: null,
  });
  // A paired surrogate is fine: U+20000 counts as 1 CJK character
  // (fixture astral-cjk covers the count; here the surrogate pair
  // alone must not be a UNICODE error).
  const astral = run({ ...base, text: "\uD840\uDC00" });
  assert.equal(astral.ok, true);
  assert.equal(astral.result.cjkChars, 1);
});

test("counting: one mixed token contributes to both counts at once", () => {
  assert.deepEqual(countText("中文abc"), { cjkChars: 2, latinWords: 1 });
  assert.deepEqual(countText("abc中文"), { cjkChars: 2, latinWords: 1 });
  assert.deepEqual(countText("中a文b"), { cjkChars: 2, latinWords: 1 });
});

test("counting: NBSP, U+2028 and U+2029 are whitespace separators", () => {
  assert.deepEqual(countText("a\u00A0b"), { cjkChars: 0, latinWords: 2 });
  assert.deepEqual(countText("a\u2028b"), { cjkChars: 0, latinWords: 2 });
  assert.deepEqual(countText("a\u2029b"), { cjkChars: 0, latinWords: 2 });
  assert.deepEqual(countText("a\u2003b"), { cjkChars: 0, latinWords: 2 });
  assert.deepEqual(countText("a\u3000b"), { cjkChars: 0, latinWords: 2 });
});

test("counting: a combining sequence counts per code point, with no CJK", () => {
  // "e" + U+0301 is 2 code points, neither CJK; the token contains
  // the ASCII letter "e", so it is 1 word.
  assert.deepEqual(countText("e\u0301"), { cjkChars: 0, latinWords: 1 });
});

test("counting: CJK punctuation, full-width and kana/hangul do not count", () => {
  assert.deepEqual(countText("，。！ＡＢＣカタカナ한글"), { cjkChars: 0, latinWords: 0 });
  // Extension A and compatibility ideographs do count.
  assert.deepEqual(countText("\u3400\uF900"), { cjkChars: 2, latinWords: 0 });
});

test("display formatting: 3599 is 59:59, 3600 is 1:00:00, larger hours have no cap", () => {
  assert.equal(formatDuration(0), "0:00");
  assert.equal(formatDuration(59), "0:59");
  assert.equal(formatDuration(60), "1:00");
  assert.equal(formatDuration(3599), "59:59");
  assert.equal(formatDuration(3600), "1:00:00");
  assert.equal(formatDuration(3661), "1:01:01");
  assert.equal(formatDuration(36000), "10:00:00");
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.text;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, zhSilentRate: 400 }), schema);
  assert.deepEqual(errorOf({ ...base, text: null }), schema);
  assert.deepEqual(errorOf(["text"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("text"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "zhSilentRate", {
    enumerable: true,
    get() {
      return "400";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.zhSilentRate = new String("400");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...base };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, zhSilentRate: "2001" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("property: silent and speaking seconds never decrease as CJK text grows", () => {
  let prevSilent = -Infinity;
  let prevSpeak = -Infinity;
  for (const count of [1, 5, 10, 100, 1000]) {
    const outcome = run({ ...base, text: "字".repeat(count) });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.silentSeconds >= prevSilent);
    assert.ok(outcome.result.speakSeconds >= prevSpeak);
    prevSilent = outcome.result.silentSeconds;
    prevSpeak = outcome.result.speakSeconds;
  }
});

test("all-zero counts are a legal success with 0:00 displays", () => {
  const outcome = run({ ...base, text: "— … !!!" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.silentSeconds, 0);
  assert.equal(outcome.result.silentDisplay, "0:00");
  assert.equal(outcome.result.speakDisplay, "0:00");
});
